export default function ChooseServices({
  open,
  onClose,
  onProceed,
  hasActiveVpc,
}: ChooseServicesProps) {
  const [selectedService, setSelectedService] = useState("");
  const [lbChooserOpen, setLbChooserOpen] = useState(false);
  const navigate = useNavigate();
  const { available } = useResourceAvailability();

  const handleClose = () => {
    setSelectedService("");
    onClose();
  };

  return (
    <>
      <Dialog open={open} onOpenChange={handleClose}>
        <DialogContent
          className="
          max-w-3xl
          p-0
          overflow-hidden
          rounded-2xl
          border
          border-border
          bg-card
          shadow-2xl
        "
        >
          <DialogHeader className="border-b border-border px-8 py-6">
            <DialogTitle className="text-2xl font-bold">
              Choose AWS Service
            </DialogTitle>

            <DialogDescription>
              Select an AWS service to continue.
            </DialogDescription>
          </DialogHeader>

          <div className="grid grid-cols-1 gap-5 px-8 md:grid-cols-2">
            {services.map((service) => {
              const limit =
                available?.[service.id]?.limit ??
                serviceLimits[service.id as keyof typeof serviceLimits] ??
                1;
              const reached = available?.[service.id]?.reached ?? false;
              const disabled = !!reached;
              const isSelected = selectedService === service.id;
              const className = `
      relative
      flex
      items-center
      gap-4
      rounded-xl
      border
      p-5
      text-left
      transition-all
      duration-300

      ${isSelected ? "border-primary bg-primary/10 ring-2 ring-primary/20" : "border-border bg-background hover:border-primary/40 hover:bg-accent/30"}
      ${disabled ? "opacity-50 cursor-not-allowed hover:!bg-background hover:!border-border" : ""}
    `;

              const content = (
                <button
                  key={service.id}
                  onClick={() => {
                    if (disabled) return;
                    setSelectedService(service.id);
                  }}
                  disabled={disabled}
                  className={`${className} w-full`}
                >
                  {isSelected && (
                    <div className="absolute right-3 top-3">
                      <div className="flex h-6 w-6 items-center justify-center rounded-full bg-primary">
                        <Check className="h-4 w-4 text-white" />
                      </div>
                    </div>
                  )}

                  <div
                    className={`flex h-14 w-14 items-center justify-center rounded-xl ${isSelected ? "bg-primary/10" : "bg-muted"}`}
                  >
                    {service.icon}
                  </div>

                  <div className="flex-1">
                    <h3 className="text-lg font-semibold">{service.title}</h3>
                    <p className="mt-1 text-sm text-muted-foreground">
                      {service.description}
                    </p>
                  </div>
                </button>
              );

              const tooltipText = `Maximum ${service.title} limit ${limit} reached.`;

              return disabled ? (
                <Tooltip key={service.id}>
                  <TooltipTrigger asChild>
                    <span className="w-full block">{content}</span>
                  </TooltipTrigger>
                  <TooltipContent side="top">
                    <p>{tooltipText}</p>
                  </TooltipContent>
                </Tooltip>
              ) : (
                content
              );
            })}
          </div>

          <div className="flex justify-end gap-3 border-t border-border bg-muted/20 px-8 py-5">
            <Button variant="outline" onClick={handleClose}>
              Cancel
            </Button>

            <Button
              disabled={!selectedService}
              onClick={() => {
                if (selectedService === "elb") {
                  setLbChooserOpen(true);
                  return;
                }
                const route = SERVICE_ROUTES[selectedService];
                handleClose();
                if (onProceed) onProceed(selectedService);
                if (route) navigate(route);
              }}
            >
              Proceed
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      <LbTypeChooserDialog
        open={lbChooserOpen}
        onOpenChange={setLbChooserOpen}
        onSelect={(type) => {
          setLbChooserOpen(false);
          handleClose();
          if (onProceed) onProceed("elb");
          navigate(`/aws/load-balancers/create/${type}`);
        }}
      />
    </>
  );
}
